      "Please set the VITE_SB_PUBLISHABLE_KEY environment variable",
    );
  }
  return withLifecycleCallbacks(
    getDataProviderWithCustomMethods(),
    lifeCycleCallbacks,
  ) as CrmDataProvider;
};

const applyFullTextSearch = (columns: string[]) => (params: GetListParams) => {
  if (!params.filter?.q) {
    return params;
  }
  const { q, ...filter } = params.filter;
  return {
    ...params,
    filter: {
      ...filter,
      "@or": columns.reduce((acc, column) => {
        if (column === "email")
          return {
            ...acc,
            [`email_fts@ilike`]: q,
          };
        if (column === "phone")
          return {
            ...acc,
            [`phone_fts@ilike`]: q,
          };
        else
          return {
            ...acc,
            [`${column}@ilike`]: q,
          };
      }, {}),
    },
  };
};

const uploadToBucket = async (fi: RAFile) => {
  if (!fi.src.startsWith("blob:") && !fi.src.startsWith("data:")) {
    // Sign URL check if path exists in the bucket
    if (fi.path) {
      const { error } = await getSupabaseClient()
        .storage.from(ATTACHMENTS_BUCKET)
        .createSignedUrl(fi.path, 60);

      if (!error) {
        return fi;
      }
    }
  }

  const dataContent = fi.src
    ? await fetch(fi.src)
        .then((res) => {
          if (res.status !== 200) {
            return null;
          }
          return res.blob();
        })
        .catch(() => null)
    : fi.rawFile;

  if (dataContent == null) {
    // We weren't able to download the file from its src (e.g. user must be signed in on another website to access it)
    // or the file has no content (not probable)
    // In that case, just return it as is: when trying to download it, users should be redirected to the other website
    // and see they need to be signed in. It will then be their responsibility to upload the file back to the note.
    return fi;
  }

  const file = fi.rawFile;
  const fileParts = file.name.split(".");
  const fileExt = fileParts.length > 1 ? `.${file.name.split(".").pop()}` : "";
  const fileName = `${Math.random()}${fileExt}`;
  const filePath = `${fileName}`;
  const { error: uploadError } = await getSupabaseClient()
    .storage.from(ATTACHMENTS_BUCKET)
    .upload(filePath, dataContent);

  if (uploadError) {
    console.error("uploadError", uploadError);
    throw new Error("Failed to upload attachment");
  }

  const { data } = getSupabaseClient()
    .storage.from(ATTACHMENTS_BUCKET)
    .getPublicUrl(filePath);

  fi.path = filePath;
  fi.src = data.publicUrl;

  // save MIME type
  const mimeType = file.type;
  fi.type = mimeType;

  return fi;
};

import type { AuthProvider } from "ra-core";
import { supabaseAuthProvider } from "ra-supabase-core";

import { canAccess } from "../commons/canAccess";
import { getSupabaseClient } from "./supabase";

const getBaseAuthProvider = () =>
  supabaseAuthProvider(getSupabaseClient(), {
    getIdentity: async () => {
      const sale = await getSale();

      if (sale == null) {
        throw new Error();
      }

      return {
        id: sale.id,
        fullName: `${sale.first_name} ${sale.last_name}`,
        avatar: sale.avatar?.src,
      };
    },
  });

// To speed up checks, we cache the initialization state
// and the current sale in the local storage. They are cleared on logout.
const IS_INITIALIZED_CACHE_KEY = "RaStore.auth.is_initialized";
const CURRENT_SALE_CACHE_KEY = "RaStore.auth.current_sale";

function getLocalStorage(): Storage | null {
  if (typeof window !== "undefined" && window.localStorage) {
    return window.localStorage;
  }
  return null;
}

export async function getIsInitialized() {
  const storage = getLocalStorage();
  const cachedValue = storage?.getItem(IS_INITIALIZED_CACHE_KEY);
  if (cachedValue != null) {
    return cachedValue === "true";
  }

  const { data } = await getSupabaseClient()
    .from("init_state")
    .select("is_initialized");
  const isInitialized = data?.at(0)?.is_initialized > 0;

  if (isInitialized) {
    storage?.setItem(IS_INITIALIZED_CACHE_KEY, "true");
  }

  return isInitialized;
}

const getSale = async () => {
  const storage = getLocalStorage();
  const cachedValue = storage?.getItem(CURRENT_SALE_CACHE_KEY);
  if (cachedValue != null) {
    return JSON.parse(cachedValue);
  }

  const { data: dataSession, error: errorSession } =
    await getSupabaseClient().auth.getSession();

  // Shouldn't happen after login but just in case
  if (dataSession?.session?.user == null || errorSession) {
    return undefined;
  }

  const { data: dataSale, error: errorSale } = await getSupabaseClient()
    .from("sales")
    .select("id, first_name, last_name, avatar, administrator")
    .match({ user_id: dataSession?.session?.user.id })
    .single();

  // Shouldn't happen either as all users are sales but just in case
  if (dataSale == null || errorSale) {
    return undefined;
  }

  storage?.setItem(CURRENT_SALE_CACHE_KEY, JSON.stringify(dataSale));
  return dataSale;
};

function clearCache() {
  const storage = getLocalStorage();
  storage?.removeItem(IS_INITIALIZED_CACHE_KEY);
  storage?.removeItem(CURRENT_SALE_CACHE_KEY);
}

export const getAuthProvider = (): AuthProvider => {
  const baseAuthProvider = getBaseAuthProvider();
  return {
    ...baseAuthProvider,
    login: async (params) => {
      if (params.ssoDomain) {
        const { error } = await getSupabaseClient().auth.signInWithSSO({
          domain: params.ssoDomain,
        });
        if (error) {
          throw error;
        }
        return;
      }
      return baseAuthProvider.login(params);
    },
    logout: async (params) => {
      clearCache();
      return baseAuthProvider.logout(params);
    },
    checkAuth: async (params) => {
      // Users are on the set-password page, nothing to do
      if (
        window.location.pathname === "/set-password" ||
        window.location.hash.includes("#/set-password")
      ) {
        return;
      }
      // Users are on the forgot-password page, nothing to do
      if (
        window.location.pathname === "/forgot-password" ||
        window.location.hash.includes("#/forgot-password")
      ) {
        return;
      }
      // Users are on the sign-up page, nothing to do
      if (
        window.location.pathname === "/sign-up" ||
        window.location.hash.includes("#/sign-up")
      ) {
        return;
      }

      const isInitialized = await getIsInitialized();

      if (!isInitialized) {
        await getSupabaseClient().auth.signOut();
        throw {
          redirectTo: "/sign-up",
          message: false,
        };
      }

      return baseAuthProvider.checkAuth(params);
    },
    canAccess: async (params) => {
      const isInitialized = await getIsInitialized();
      if (!isInitialized) return false;

      // Get the current user
      const sale = await getSale();
      if (sale == null) return false;

      // Compute access rights from the sale role
      const role = sale.administrator ? "admin" : "user";
      return canAccess(role, params);
    },
    getAuthorizationDetails(authorizationId: string) {
      return getSupabaseClient().auth.oauth.getAuthorizationDetails(
        authorizationId,
      );
    },
    approveAuthorization(authorizationId: string) {
      return getSupabaseClient().auth.oauth.approveAuthorization(
        authorizationId,
      );
    },
    denyAuthorization(authorizationId: string) {
      return getSupabaseClient().auth.oauth.denyAuthorization(authorizationId);
    },
  };
};

import type { DataProvider, Identifier } from "ra-core";

import type {
  Company,
  Contact,
  ContactNote,
  Deal,
  DealNote,
  SearchResourceName,
  SearchResult,
  Task,
} from "../../types";
import {
  DESKTOP_SEARCH_RESOURCES,
  getSearchTerms,
  matchesAllTerms,
} from "../../search/searchModel";

const DEFAULT_MAX_RESULTS = 50;
const TITLE_LENGTH = 200;

const getAll = async <T>(
  dataProvider: DataProvider,
  resource: string,
): Promise<T[]> => {
  const { data } = await dataProvider.getList<any>(resource, {
    filter: {},
    pagination: { page: 1, perPage: Number.MAX_SAFE_INTEGER },
    sort: { field: "id", order: "ASC" },
  });
  return data as T[];
};

const contactName = (contact: Pick<Contact, "first_name" | "last_name">) =>
  [contact.first_name, contact.last_name].filter(Boolean).join(" ");

// Same fields, same separator as the `content` column of `global_search`.
const joinFields = (...values: (string | null | undefined)[]) =>
  values.filter(Boolean).join(" · ") || null;

const attachmentTitles = (note: ContactNote | DealNote) =>
  note.attachments?.map((attachment) => attachment.title).join(" ");

const byDateDesc = (a: SearchResult, b: SearchResult) =>
  (b.date ?? "").localeCompare(a.date ?? "");

/** A result, plus the text its table's `fts` column indexes in Postgres. */
type Candidate = { result: SearchResult; document: string };

/**
 * Emulates the `global_search` database function for the FakeRest provider.
 *
 * It follows the same rules: the same fields per resource, every query word
 * must start a word of the record (accents and case ignored), open tasks and
 * live deals only, each resource's newest `maxResults` matches, newest first.
 * It scans every record, which is fine for the in-browser demo data.
 */
export async function getSearchResults(
  dataProvider: DataProvider,
  query: string,
  resources: readonly SearchResourceName[] = DESKTOP_SEARCH_RESOURCES,
  maxResults = DEFAULT_MAX_RESULTS,
): Promise<SearchResult[]> {
  const terms = getSearchTerms(query);
  if (terms.length === 0) {
    return [];
  }

  const [companies, contacts, deals, tasks, contactNotes, dealNotes] =
    await Promise.all([
      getAll<Company>(dataProvider, "companies"),
      getAll<Contact>(dataProvider, "contacts"),
      getAll<Deal>(dataProvider, "deals"),
      getAll<Task>(dataProvider, "tasks"),
      getAll<ContactNote>(dataProvider, "contact_notes"),
      getAll<DealNote>(dataProvider, "deal_notes"),
    ]);

  const companiesById = new Map<Identifier, Company>(
    companies.map((company) => [company.id, company]),
  );
  const contactsById = new Map<Identifier, Contact>(
    contacts.map((contact) => [contact.id, contact]),
  );
  const dealsById = new Map<Identifier, Deal>(
    deals.map((deal) => [deal.id, deal]),
  );
  const companyName = (id: Identifier | null | undefined) =>
    id != null ? (companiesById.get(id)?.name ?? null) : null;
  const contactLabel = (id: Identifier) => {
    const contact = contactsById.get(id);
    return contact ? contactName(contact) : null;
  };
  const liveDeals = deals.filter((deal) => !deal.archived_at);

  const candidates: Record<SearchResourceName, () => Candidate[]> = {
    companies: () =>
      companies.map((company) => {
        const content = joinFields(
          company.sector,
          company.description,
          company.website,
          company.phone_number,
          company.zipcode,
          company.city,
          company.state_abbr,
        );
        return {
          document: [company.name, content].join(" "),
          result: {
            resource: "companies",
            record_id: company.id,
            title: company.name,
            subtitle: company.sector ?? null,
            contact_id: null,
            deal_id: null,
            date: company.created_at ?? null,
            content,
          },
        };
      }),
    contacts: () =>
      contacts.map((contact) => {
        const content = joinFields(
          contact.title,
          contact.background,
          contact.email_jsonb?.map(({ email }) => email).join(" "),
          contact.phone_jsonb?.map(({ number }) => number).join(" "),
        );
        return {
          document: [contact.first_name, contact.last_name, content].join(" "),
          result: {
            resource: "contacts",
            record_id: contact.id,
            title: contactName(contact),
            subtitle: companyName(contact.company_id),
            contact_id: contact.id,
            deal_id: null,
            date: contact.first_seen ?? null,
            content,
          },
        };
      }),
    deals: () =>
      liveDeals.map((deal) => {
        const content = joinFields(deal.category, deal.description);
        return {
          document: [deal.name, content].join(" "),
          result: {
            resource: "deals",
            record_id: deal.id,
            title: deal.name,
            subtitle: companyName(deal.company_id),
            contact_id: null,
            deal_id: deal.id,
            date: deal.created_at ?? null,
            content,
          },
        };
      }),
    tasks: () =>
      tasks
        .filter((task) => !task.done_date)
        .map((task) => {
          const content = joinFields(task.text, task.type);
          return {
            document: content ?? "",
            result: {
              resource: "tasks",
              record_id: task.id,
              title: task.text?.slice(0, TITLE_LENGTH) ?? null,
              subtitle: contactLabel(task.contact_id),
              contact_id: task.contact_id,
              deal_id: null,
              date: task.created_at ?? null,
              content,
            },
          };
        }),
    contact_notes: () =>
      contactNotes.map((note) => {
        const content = joinFields(note.text, attachmentTitles(note));
        return {
          document: content ?? "",
          result: {
            resource: "contact_notes",
            record_id: note.id,
            title: note.text?.slice(0, TITLE_LENGTH) ?? null,
            subtitle: contactLabel(note.contact_id),
            contact_id: note.contact_id,
            deal_id: null,
            date: note.date ?? null,
            content,
          },
        };
      }),
    deal_notes: () =>
      dealNotes
        .filter((note) => {
          const deal = dealsById.get(note.deal_id);
          return deal != null && !deal.archived_at;
        })
        .map((note) => {
          const content = joinFields(note.text, attachmentTitles(note));
          return {
            document: content ?? "",
            result: {
              resource: "deal_notes",
              record_id: note.id,
              title: note.text?.slice(0, TITLE_LENGTH) ?? null,
              subtitle: dealsById.get(note.deal_id)?.name ?? null,
              contact_id: null,
              deal_id: note.deal_id,
              date: note.date ?? null,
              content,
            },
          };
        }),
  };

  return resources
    .flatMap((resource) =>
      candidates[resource]()
        .filter(({ document }) => matchesAllTerms(document, terms))
        .map(({ result }) => result)
        .sort(byDateDesc)
        .slice(0, maxResults),
    )
    .sort(byDateDesc);
}

