import type { Db } from "./types";
import { CONTACT_NOTES } from "./samples";
import { randomDate } from "./utils";

export const generateContactNotes = (db: Db): ContactNote[] => {
  return Array.from(Array(160).keys()).map((id) => {
    const contact = random.arrayElement(db.contacts);
    const date = randomDate(new Date(contact.first_seen));
    contact.last_seen =
      date > new Date(contact.last_seen)
        ? date.toISOString()
        : contact.last_seen;
    return {
      id,
      contact_id: contact.id,
      text: random.arrayElement(CONTACT_NOTES),
      date: date.toISOString(),
      sales_id: contact.sales_id!,
      status: random.arrayElement(defaultNoteStatuses).value,
    };
  });
};

